def test_integer_pose_identities_keep_distinct_render_colors_and_detected_rackets(tmp_path, monkeypatch): original_line, original_rectangle = current.cv2.line, current.cv2.rectangle colors, racket_boxes = set(), []
def line(frame, first, second, color, *args): if color in ((220, 210, 40), (40, 180, 255)): colors.add(color) return original_line(frame, first, second, color, *args)
